// WP-7.3 path-tracing mode on Vulkan: see include/fuse/renderer/pathtrace/pt_gpu.hpp.
#include <fuse/renderer/pathtrace/pt_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp73.cmake from shaders/pathtrace/*: kPt<Stage><Slang|Glsl>Spv and FUSE_PT_{SLANG,GLSL}
// when every stage of a language exists.
#include "pathtrace_spv.h"
#endif

namespace fuse::renderer::pathtrace {

namespace {
constexpr u32 kFrameStride = 512u; ///< ring slot size (>= sizeof(PtFrameConstants), 256-aligned)
static_assert(sizeof(PtFrameConstants) <= kFrameStride, "frame ring slot");
constexpr u8 kCs = rg::kStageCompute;
/// Stages of the embedded kernels (the order of the SPIR-V table below).
enum Stage : u32 { kStageTrace = 0, kStageRaygen, kStageMiss, kStageClosestHit, kStageAnyHit, kStageCount };

[[maybe_unused]] u32 groups(u32 items, u32 size) { return items == 0u ? 1u : (items + size - 1u) / size; }
u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

bool sameCamera(const PtCamera& a, const PtCamera& b) {
    return std::memcmp(a.viewProj, b.viewProj, sizeof(a.viewProj)) == 0 && std::memcmp(a.position, b.position, sizeof(a.position)) == 0;
}
} // namespace

PtCapabilities queryPtCapabilities(const VulkanDevice* device) {
    PtCapabilities caps{};
    if (device == nullptr || !device->isValid()) {
        return caps;
    }
#if defined(FUSE_VULKAN_BACKEND)
    caps = evaluatePtCapabilities(device->info().caps);
#if !defined(FUSE_PT_SLANG) && !defined(FUSE_PT_GLSL)
    caps.rayQuery = false;
    caps.rayTracingPipeline = false;
    caps.reason = caps.pipelineReason = "path-tracing kernels not built (no shader compiler)";
#endif
#else
    caps.reason = caps.pipelineReason = "stub backend";
#endif
    return caps;
}

PathTracerGpu::~PathTracerGpu() { destroy(); }

void PathTracerGpu::setSettings(const PtSettings& settings) {
    m_settings = ptSanitize(settings);
    m_settingsDirty = true;
}

bool PathTracerGpu::init(const PathTracerGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.device == nullptr || desc.allocator == nullptr || desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots) {
        m_reason = "device / allocator / framesInFlight (1..8) missing";
        return false;
    }
    m_caps = queryPtCapabilities(desc.device);
    if (!m_caps.rayQuery) {
        m_reason = m_caps.reason;
        return false;
    }
    if (desc.backend == PtBackend::RayTracingPipeline && !m_caps.rayTracingPipeline) {
        m_reason = m_caps.pipelineReason;
        return false;
    }
    m_rtPipeline = desc.backend == PtBackend::RayTracingPipeline || (desc.backend == PtBackend::Auto && m_caps.rayTracingPipeline);
    m_initialized = true; // destroy() releases partial state from here on
    BufferDesc ring{};
    ring.size = static_cast<usize>(desc.framesInFlight) * kFrameStride;
    ring.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    ring.memoryUsage = MemoryUsage::CpuToGpu;
    ring.name = "pathtrace.frame";
    if (!m_desc.allocator->createBuffer(ring, m_frameRing) || m_frameRing.mapped == nullptr || m_frameRing.deviceAddress == 0u) {
        destroy();
        m_reason = "frame ring allocation failed";
        return false;
    }
    const u64 tableBytes = align256(static_cast<u64>(std::max(desc.initialLights, 1u)) * sizeof(restir::RestirLight)) +
                           align256(static_cast<u64>(std::max(desc.initialMapWords, 1u)) * 4u);
    if (!ensureTableCapacity(tableBytes)) {
        destroy();
        m_reason = "light table allocation failed";
        return false;
    }
    if (!createPipelines()) {
        destroy();
        m_reason = m_rtPipeline ? "ray-tracing pipeline / SBT creation failed or kernels not built for the language"
                                : "ray-query kernel not built for the requested language / pipeline creation failed";
        return false;
    }
    if (desc.width > 0u && desc.height > 0u && !createBuffers(desc.width, desc.height)) {
        destroy();
        m_reason = "buffer allocation failed";
        return false;
    }
    m_settings = ptSanitize(m_settings);
    m_reason = "ok";
    return true;
#else
    m_reason = "stub backend";
    return false;
#endif
}

void PathTracerGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    for (Buffer* b : {&m_state, &m_output, &m_frameRing, &m_tableRing}) {
        if (b->handle != nullptr) {
            m_desc.allocator->destroyBuffer(*b);
        }
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
    if (m_sbtBuffer != nullptr) {
        vkDestroyBuffer(device, static_cast<VkBuffer>(m_sbtBuffer), nullptr);
    }
    if (m_sbtMemory != nullptr) {
        vkFreeMemory(device, static_cast<VkDeviceMemory>(m_sbtMemory), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_sbtBuffer = nullptr;
    m_sbtMemory = nullptr;
    m_sbtAddress = 0;
    m_traceRays = nullptr;
    m_sbt = PtSbtLayout{};
    m_state = Buffer{};
    m_output = Buffer{};
    m_frameRing = Buffer{};
    m_tableRing = Buffer{};
    m_stateQueue = m_outputQueue = m_tableQueue = rg::kNoQueue;
    m_frameAddress = 0;
    m_tableSlotBytes = 0;
    for (u32 i = 0; i < kMaxSlots; ++i) {
        m_slotValid[i] = false;
    }
    for (Retired& r : m_retired) {
        r = Retired{};
    }
    m_layout = PtBufferLayout{};
    m_restart = true;
    m_samples = 0;
    m_language = "none";
    m_rtPipeline = false;
    m_stats = PtGpuStats{};
    m_initialized = false;
}

bool PathTracerGpu::createPipelines() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words[kStageCount] = {};
    usize bytes[kStageCount] = {};
    bool found = false;
    auto take = [&](u32 stage, const u32* w, usize b) {
        words[stage] = w;
        bytes[stage] = b;
    };
#if defined(FUSE_PT_SLANG)
    if (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Slang) {
        take(kStageTrace, kPtTraceSlangSpv, sizeof(kPtTraceSlangSpv));
        take(kStageRaygen, kPtRaygenSlangSpv, sizeof(kPtRaygenSlangSpv));
        take(kStageMiss, kPtMissSlangSpv, sizeof(kPtMissSlangSpv));
        take(kStageClosestHit, kPtClosestHitSlangSpv, sizeof(kPtClosestHitSlangSpv));
        take(kStageAnyHit, kPtAnyHitSlangSpv, sizeof(kPtAnyHitSlangSpv));
        m_language = "slang";
        found = true;
    }
#endif
#if defined(FUSE_PT_GLSL)
    if (!found && (m_desc.language == PtKernelLanguage::Auto || m_desc.language == PtKernelLanguage::Glsl)) {
        take(kStageTrace, kPtTraceGlslSpv, sizeof(kPtTraceGlslSpv));
        take(kStageRaygen, kPtRaygenGlslSpv, sizeof(kPtRaygenGlslSpv));
        take(kStageMiss, kPtMissGlslSpv, sizeof(kPtMissGlslSpv));
        take(kStageClosestHit, kPtClosestHitGlslSpv, sizeof(kPtClosestHitGlslSpv));
        take(kStageAnyHit, kPtAnyHitGlslSpv, sizeof(kPtAnyHitGlslSpv));
        m_language = "glsl";
        found = true;
    }
#endif
    (void)take;
    if (!found) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkPushConstantRange range{};
    range.stageFlags = m_rtPipeline ? (VK_SHADER_STAGE_RAYGEN_BIT_KHR | VK_SHADER_STAGE_MISS_BIT_KHR | VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR |
                                       VK_SHADER_STAGE_ANY_HIT_BIT_KHR)
                                    : VK_SHADER_STAGE_COMPUTE_BIT;
    range.offset = 0;
    range.size = sizeof(PtPush);
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    if (m_rtPipeline) {
        return createRtPipeline(words, bytes);
    }
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes[kStageTrace];
    moduleInfo.pCode = words[kStageTrace];
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = m_desc.bindless != nullptr ? static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags()) : 0u;
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool PathTracerGpu::createRtPipeline(const u32* const* words, const usize* bytes) {
#if defined(FUSE_VULKAN_BACKEND) && defined(VK_KHR_ray_tracing_pipeline)
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    const VkPhysicalDevice physical = static_cast<VkPhysicalDevice>(m_desc.device->nativePhysicalDevice());
    auto createRt = reinterpret_cast<PFN_vkCreateRayTracingPipelinesKHR>(vkGetDeviceProcAddr(device, "vkCreateRayTracingPipelinesKHR"));
    auto getHandles =
        reinterpret_cast<PFN_vkGetRayTracingShaderGroupHandlesKHR>(vkGetDeviceProcAddr(device, "vkGetRayTracingShaderGroupHandlesKHR"));
    m_traceRays = reinterpret_cast<void*>(vkGetDeviceProcAddr(device, "vkCmdTraceRaysKHR"));
    if (createRt == nullptr || getHandles == nullptr || m_traceRays == nullptr) {
        return false;
    }
    VkPhysicalDeviceRayTracingPipelinePropertiesKHR rtProps{};
    rtProps.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_PIPELINE_PROPERTIES_KHR;
    VkPhysicalDeviceProperties2 props{};
    props.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
    props.pNext = &rtProps;
    vkGetPhysicalDeviceProperties2(physical, &props);
    if (rtProps.maxRayRecursionDepth < 1u) {
        return false;
    }
    m_sbt = computePtSbtLayout(rtProps.shaderGroupHandleSize, rtProps.shaderGroupHandleAlignment, rtProps.shaderGroupBaseAlignment,
                               rtProps.maxShaderGroupStride);
    if (!m_sbt.valid) {
        return false;
    }
    // Stages: raygen, miss, closest hit, any hit.
    const Stage order[4] = {kStageRaygen, kStageMiss, kStageClosestHit, kStageAnyHit};
    const VkShaderStageFlagBits vkStages[4] = {VK_SHADER_STAGE_RAYGEN_BIT_KHR, VK_SHADER_STAGE_MISS_BIT_KHR,
                                               VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR, VK_SHADER_STAGE_ANY_HIT_BIT_KHR};
    VkShaderModule modules[4] = {};
    VkPipelineShaderStageCreateInfo stages[4]{};
    bool ok = true;
    for (u32 i = 0; i < 4u && ok; ++i) {
        VkShaderModuleCreateInfo moduleInfo{};
        moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
        moduleInfo.codeSize = bytes[order[i]];
        moduleInfo.pCode = words[order[i]];
        ok = vkCreateShaderModule(device, &moduleInfo, nullptr, &modules[i]) == VK_SUCCESS;
        stages[i].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
        stages[i].stage = vkStages[i];
        stages[i].module = modules[i];
        stages[i].pName = "main";
    }
    VkRayTracingShaderGroupCreateInfoKHR groupsInfo[kPtGroupCount]{};
    for (VkRayTracingShaderGroupCreateInfoKHR& g : groupsInfo) {
        g.sType = VK_STRUCTURE_TYPE_RAY_TRACING_SHADER_GROUP_CREATE_INFO_KHR;
        g.generalShader = VK_SHADER_UNUSED_KHR;
        g.closestHitShader = VK_SHADER_UNUSED_KHR;
        g.anyHitShader = VK_SHADER_UNUSED_KHR;
        g.intersectionShader = VK_SHADER_UNUSED_KHR;
    }
    groupsInfo[kPtGroupRaygen].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_GENERAL_KHR;
    groupsInfo[kPtGroupRaygen].generalShader = 0;
    groupsInfo[kPtGroupMiss].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_GENERAL_KHR;
    groupsInfo[kPtGroupMiss].generalShader = 1;
    groupsInfo[kPtGroupHit].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR;
    groupsInfo[kPtGroupHit].closestHitShader = 2;
    groupsInfo[kPtGroupHit].anyHitShader = 3;
    groupsInfo[kPtGroupShadowHit].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR;
    groupsInfo[kPtGroupShadowHit].anyHitShader = 3;
    VkPipeline pipeline = VK_NULL_HANDLE;
    if (ok) {
        VkRayTracingPipelineCreateInfoKHR info{};
        info.sType = VK_STRUCTURE_TYPE_RAY_TRACING_PIPELINE_CREATE_INFO_KHR;
        info.flags = m_desc.bindless != nullptr ? static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags()) : 0u;
        info.stageCount = 4;
        info.pStages = stages;
        info.groupCount = kPtGroupCount;
        info.pGroups = groupsInfo;
        info.maxPipelineRayRecursionDepth = 1;
        info.layout = static_cast<VkPipelineLayout>(m_layoutHandle);
        ok = createRt(device, VK_NULL_HANDLE, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline) == VK_SUCCESS;
    }
    for (VkShaderModule m : modules) {
        if (m != VK_NULL_HANDLE) {
            vkDestroyShaderModule(device, m, nullptr);
        }
    }
    m_pipeline = pipeline;
    if (!ok) {
        return false;
    }
    // Shader binding table: host-visible, device-addressable (the allocator has no SBT usage bit, so the buffer is
    // created here; it is written once and never changes, hence never imported into the graph).
    u8 handles[kPtGroupCount * 64u] = {};
    if (rtProps.shaderGroupHandleSize > 64u ||
        getHandles(device, pipeline, 0, kPtGroupCount, kPtGroupCount * rtProps.shaderGroupHandleSize, handles) != VK_SUCCESS) {
        return false;
    }
    VkBufferCreateInfo bufferInfo{};
    bufferInfo.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
    bufferInfo.size = m_sbt.bytes + rtProps.shaderGroupBaseAlignment;
    bufferInfo.usage = VK_BUFFER_USAGE_SHADER_BINDING_TABLE_BIT_KHR | VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT;
    bufferInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    VkBuffer buffer = VK_NULL_HANDLE;
    if (vkCreateBuffer(device, &bufferInfo, nullptr, &buffer) != VK_SUCCESS) {
        return false;
    }
    m_sbtBuffer = buffer;
    VkMemoryRequirements req{};
    vkGetBufferMemoryRequirements(device, buffer, &req);
    VkPhysicalDeviceMemoryProperties mem{};
    vkGetPhysicalDeviceMemoryProperties(physical, &mem);
    const VkMemoryPropertyFlags want = VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;
    u32 type = UINT32_MAX;
    for (u32 i = 0; i < mem.memoryTypeCount; ++i) {
        if ((req.memoryTypeBits & (1u << i)) != 0u && (mem.memoryTypes[i].propertyFlags & want) == want) {
            type = i;
            break;
        }
    }
    if (type == UINT32_MAX) {
        return false;
    }
    VkMemoryAllocateFlagsInfo flagsInfo{};
    flagsInfo.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_FLAGS_INFO;
    flagsInfo.flags = VK_MEMORY_ALLOCATE_DEVICE_ADDRESS_BIT;
    VkMemoryAllocateInfo allocInfo{};
    allocInfo.sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO;
    allocInfo.pNext = &flagsInfo;
    allocInfo.allocationSize = req.size;
    allocInfo.memoryTypeIndex = type;
    VkDeviceMemory memory = VK_NULL_HANDLE;
    if (vkAllocateMemory(device, &allocInfo, nullptr, &memory) != VK_SUCCESS) {
        return false;
    }
    m_sbtMemory = memory;
    if (vkBindBufferMemory(device, buffer, memory, 0) != VK_SUCCESS) {
        return false;
    }
    VkBufferDeviceAddressInfo addressInfo{};
    addressInfo.sType = VK_STRUCTURE_TYPE_BUFFER_DEVICE_ADDRESS_INFO;
    addressInfo.buffer = buffer;
    const u64 base = vkGetBufferDeviceAddress(device, &addressInfo);
    const u64 alignment = rtProps.shaderGroupBaseAlignment;
    m_sbtAddress = (base + alignment - 1u) / alignment * alignment;
    void* mapped = nullptr;
    if (vkMapMemory(device, memory, 0, VK_WHOLE_SIZE, 0, &mapped) != VK_SUCCESS) {
        return false;
    }
    u8* dst = static_cast<u8*>(mapped) + (m_sbtAddress - base);
    const u32 hs = rtProps.shaderGroupHandleSize;
    std::memcpy(dst + m_sbt.raygen.offset, handles + kPtGroupRaygen * hs, hs);
    std::memcpy(dst + m_sbt.miss.offset, handles + kPtGroupMiss * hs, hs);
    std::memcpy(dst + m_sbt.hit.offset, handles + kPtGroupHit * hs, hs);
    std::memcpy(dst + m_sbt.hit.offset + m_sbt.hit.stride, handles + kPtGroupShadowHit * hs, hs);
    vkUnmapMemory(device, memory);
    return true;
#else
    (void)words;
    (void)bytes;
    return false;
#endif
}

bool PathTracerGpu::createBuffers(u32 width, u32 height) {
    const PtBufferLayout layout = PtBufferLayout::compute(width, height);
    Buffer fresh[2]{};
    const u64 sizes[2] = {layout.stateBytes, layout.outputBytes};
    const char* names[2] = {"pathtrace.state", "pathtrace.output"};
    bool ok = true;
    for (u32 i = 0; i < 2u && ok; ++i) {
        BufferDesc d{};
        d.size = static_cast<usize>(sizes[i]);
        d.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                           static_cast<u32>(BufferUsage::TransferSrc));
        d.memoryUsage = MemoryUsage::GpuOnly;
        d.name = names[i];
        ok = m_desc.allocator->createBuffer(d, fresh[i]) && fresh[i].deviceAddress != 0u;
    }
    if (!ok) {
        for (Buffer& b : fresh) {
            if (b.handle != nullptr) {
                m_desc.allocator->destroyBuffer(b);
            }
        }
        return false;
    }
    if (m_state.handle != nullptr || m_output.handle != nullptr) {
        Retired old{};
        old.buffers[0] = m_state;
        old.buffers[1] = m_output;
        if (!retire(old)) {
            for (Buffer& b : fresh) {
                m_desc.allocator->destroyBuffer(b);
            }
            return false;
        }
    }
    m_state = fresh[0];
    m_output = fresh[1];
    m_stateQueue = m_outputQueue = rg::kNoQueue;
    m_layout = layout;
    m_restart = true;
    ++m_stats.rebuilds;
    return true;
}

bool PathTracerGpu::ensureTableCapacity(u64 bytes) {
    const u64 slotBytes = align256(std::max<u64>(bytes, 256u));
    if (m_tableRing.handle != nullptr && slotBytes <= m_tableSlotBytes) {
        return true;
    }
    const u64 grown = std::max<u64>(slotBytes, m_tableSlotBytes * 2u);
    BufferDesc d{};
    d.size = static_cast<usize>(grown * m_desc.framesInFlight);
    d.usage = static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) | static_cast<u32>(BufferUsage::ShaderDeviceAddress));
    d.memoryUsage = MemoryUsage::CpuToGpu;
    d.name = "pathtrace.tables";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_tableRing.handle != nullptr) {
        Retired old{};
        old.buffers[2] = m_tableRing;
        if (!retire(old)) {
            m_desc.allocator->destroyBuffer(fresh);
            return false;
        }
    }
    m_tableRing = fresh;
    m_tableQueue = rg::kNoQueue;
    m_tableSlotBytes = grown;
    for (u32 i = 0; i < kMaxSlots; ++i) {
        m_slotValid[i] = false;
    }
    return true;
}

bool PathTracerGpu::retire(const Retired& r) {
    for (Retired& slot : m_retired) {
        if (!slot.used) {
            slot = r;
            slot.serial = m_frameSerial;
            slot.used = true;
            return true;
        }
    }
    return false;
}

u32 PathTracerGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    for (Retired& r : m_retired) {
        if (!r.used || r.serial > completedSerial) {
            continue;
        }
        for (Buffer& b : r.buffers) {
            if (b.handle != nullptr) {
                m_desc.allocator->destroyBuffer(b);
            }
        }
        r = Retired{};
        ++collected;
    }
    return collected;
}

bool PathTracerGpu::beginFrame(u64 frameSerial, const PtFrameDesc& desc) {
    if (!m_initialized || desc.width == 0u || desc.height == 0u || desc.tlasAddress == 0u || desc.sceneHeader == 0u ||
        (desc.lightTreeHeader != 0u && (desc.lights == nullptr || desc.lightCount == 0u)) ||
        (desc.emitterMap != nullptr && desc.emitterMapWords < desc.emitterMapSlots)) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_stats.passes = 0;
    if ((desc.width != m_layout.width || desc.height != m_layout.height || m_state.handle == nullptr) &&
        !createBuffers(desc.width, desc.height)) {
        return false;
    }
    bool restart = m_restart || desc.reset || m_settingsDirty || !sameCamera(desc.camera, m_lastCamera);
    m_settingsDirty = false;
    m_lastCamera = desc.camera;
    // Light table + emitter map: this frame's ring slot, copied when it holds another version.
    m_lightTree = desc.lightTreeHeader != 0u;
    const u32 lightCount = m_lightTree ? desc.lightCount : 0u;
    const u32 mapWords = m_lightTree && desc.emitterMap != nullptr ? desc.emitterMapWords : 0u;
    const u64 lightBytes = align256(static_cast<u64>(lightCount) * sizeof(restir::RestirLight));
    m_tableBytes = lightBytes + align256(static_cast<u64>(mapWords) * 4u);
    if (!ensureTableCapacity(m_tableBytes)) {
        return false;
    }
    if (m_haveTables && (m_lightsVersion != desc.lightsVersion || m_mapVersion != desc.emitterMapVersion)) {
        restart = true;
    }
    m_haveTables = true;
    m_lightsVersion = desc.lightsVersion;
    m_mapVersion = desc.emitterMapVersion;
    const u32 ringSlot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    m_tableOffset = static_cast<u64>(ringSlot) * m_tableSlotBytes;
    if (!m_slotValid[ringSlot] || m_slotLightsVersion[ringSlot] != desc.lightsVersion || m_slotMapVersion[ringSlot] != desc.emitterMapVersion ||
        m_slotLightCount[ringSlot] != lightCount || m_slotMapWords[ringSlot] != mapWords) {
        u8* dst = static_cast<u8*>(m_tableRing.mapped) + m_tableOffset;
        if (lightCount > 0u) {
            std::memcpy(dst, desc.lights, static_cast<usize>(lightCount) * sizeof(restir::RestirLight));
        }
        if (mapWords > 0u) {
            std::memcpy(dst + lightBytes, desc.emitterMap, static_cast<usize>(mapWords) * 4u);
        }
        m_slotValid[ringSlot] = true;
        m_slotLightsVersion[ringSlot] = desc.lightsVersion;
        m_slotMapVersion[ringSlot] = desc.emitterMapVersion;
        m_slotLightCount[ringSlot] = lightCount;
        m_slotMapWords[ringSlot] = mapWords;
        ++m_stats.tableUploads;
    }
    if (restart) {
        m_samples = 0;
        m_restart = false;
        ++m_stats.restarts;
    }
    const PtSettings& s = m_settings;
    m_traceThisFrame = !(s.accumulate && s.maxAccumulatedSamples > 0u && m_samples >= s.maxAccumulatedSamples);
    PtFrameParams params{};
    params.width = desc.width;
    params.height = desc.height;
    params.frameIndex = desc.frameIndex;
    params.seed = desc.seed;
    params.sampleBase = s.accumulate ? m_samples : 0u;
    params.lightCount = lightCount;
    params.lightTree = m_lightTree;
    params.emitterMap = mapWords > 0u;
    params.emitterMapSlots = mapWords > 0u ? desc.emitterMapSlots : 0u;
    if (!buildPtFrameConstants(s, desc.camera, params, m_constants)) {
        return false;
    }
    if (!s.accumulate) {
        // sampleBase 0 restarts the sum every frame; the RNG still needs a fresh sequence per frame.
        m_constants.seed = desc.seed ^ (desc.frameIndex * 0x9E3779B9u);
    }
    const u64 table = m_tableRing.deviceAddress + m_tableOffset;
    m_constants.tlas = desc.tlasAddress;
    m_constants.scene = desc.sceneHeader;
    m_constants.lightTree = desc.lightTreeHeader;
    m_constants.lights = lightCount > 0u ? table : 0u;
    m_constants.emitterMap = mapWords > 0u ? table + lightBytes : 0u;
    m_constants.accum = accumAddress();
    m_constants.accumSq = accumSqAddress();
    m_constants.mean = meanAddress();
    m_constants.signal = signalAddress();
    m_constants.depth = depthAddress();
    m_constants.normal = normalAddress();
    m_constants.albedo = albedoAddress();
    const u64 offset = (frameSerial % m_desc.framesInFlight) * kFrameStride;
    std::memcpy(static_cast<u8*>(m_frameRing.mapped) + offset, &m_constants, sizeof(m_constants));
    m_frameAddress = m_frameRing.deviceAddress + offset;
    if (m_traceThisFrame) {
        m_samples = (s.accumulate ? m_samples : 0u) + s.samplesPerFrame;
    }
    m_stats.samples = m_samples;
    m_stats.traced = m_traceThisFrame;
    return true;
}

PtGraphRefs PathTracerGpu::importInto(rg::Graph& graph) {
    PtGraphRefs refs{};
    if (!m_initialized || m_state.handle == nullptr) {
        return refs;
    }
    refs.state = graph.importBuffer(rg::ImportedBuffer{m_state.handle, m_state.desc.size, m_stateQueue, &m_stateQueue, "pathtrace.state"});
    refs.output =
        graph.importBuffer(rg::ImportedBuffer{m_output.handle, m_output.desc.size, m_outputQueue, &m_outputQueue, "pathtrace.output"});
    refs.lights =
        graph.importBuffer(rg::ImportedBuffer{m_tableRing.handle, m_tableRing.desc.size, m_tableQueue, &m_tableQueue, "pathtrace.tables"});
    return refs;
}

bool PathTracerGpu::addPasses(rg::Graph& graph, const PtGraphRefs& refs, const PtGraphInputs& in) {
    if (!m_initialized || !refs.state.valid() || !refs.output.valid() || !refs.lights.valid() || !in.tlas.valid() ||
        !in.scene.header.valid() || (m_lightTree && !in.lightTree.tree.valid())) {
        return false;
    }
    if (!m_traceThisFrame) {
        return true;
    }
    m_record = PassRecord{};
    m_record.self = this;
    m_record.push.frame = m_frameAddress;
    rg::PassBuilder pass = graph.addPass("pathtrace.trace", &PathTracerGpu::recordTrace, &m_record);
    const rg::BufferRange tableRange{m_tableOffset, m_tableBytes > 0u ? m_tableBytes : 256u};
    if (m_rtPipeline) {
        // Render graph v2 has no ray-tracing shader stage: ALL_COMMANDS / MEMORY_READ|WRITE covers the RT stages.
        const rg::Access read = rg::Access::ExternalRead;
        pass.use(in.tlas, read);
        if (m_lightTree) {
            pass.use(in.lightTree.tree, read, in.lightTree.range);
        }
        pass.use(refs.lights, read, tableRange);
        gpu_scene::GpuScene::useAll(pass, in.scene, read);
        if (in.scene.indices.valid()) {
            pass.use(in.scene.indices, read);
        }
        pass.use(refs.state, rg::Access::ExternalWrite);
        pass.use(refs.output, rg::Access::ExternalWrite);
    } else {
        pass.use(in.tlas, rg::Access::AccelerationStructureRead, {}, kCs);
        if (m_lightTree) {
            pass.use(in.lightTree.tree, rg::Access::StorageRead, in.lightTree.range, kCs);
        }
        pass.use(refs.lights, rg::Access::StorageRead, tableRange, kCs);
        gpu_scene::GpuScene::useAll(pass, in.scene, rg::Access::StorageRead, kCs);
        if (in.scene.indices.valid()) {
            pass.use(in.scene.indices, rg::Access::StorageRead, {}, kCs);
        }
        pass.use(refs.state, rg::Access::StorageReadWrite, {}, kCs);
        pass.use(refs.output, rg::Access::StorageWrite, {}, kCs);
    }
    m_stats.passes = 1u;
    return true;
}

denoise::DenoiseFrameDesc PathTracerGpu::denoiseFrame(u64 motionAddress, bool reset) const {
    denoise::DenoiseFrameDesc d{};
    d.width = m_layout.width;
    d.height = m_layout.height;
    d.signal = signalAddress();
    d.motion = motionAddress;
    d.depth = depthAddress();
    d.normal = normalAddress();
    d.reset = reset;
    return d;
}

denoise::DenoiseGraphInputs PathTracerGpu::denoiseInputs(const PtGraphRefs& refs, rg::BufferRef motion) const {
    denoise::DenoiseGraphInputs in{};
    in.signal = refs.output;
    in.motion = motion;
    in.depth = refs.output;
    in.normal = refs.output;
    return in;
}

void PathTracerGpu::recordTrace(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const PathTracerGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    const VkPipelineLayout layout = static_cast<VkPipelineLayout>(self.m_layoutHandle);
    const u32 w = self.m_layout.width;
    const u32 h = self.m_layout.height;
#if defined(VK_KHR_ray_tracing_pipeline)
    if (self.m_rtPipeline) {
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_RAY_TRACING_KHR, static_cast<VkPipeline>(self.m_pipeline));
        vkCmdPushConstants(cmd, layout,
                           VK_SHADER_STAGE_RAYGEN_BIT_KHR | VK_SHADER_STAGE_MISS_BIT_KHR | VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR |
                               VK_SHADER_STAGE_ANY_HIT_BIT_KHR,
                           0, sizeof(PtPush), &r.push);
        const PtSbtLayout& s = self.m_sbt;
        const VkStridedDeviceAddressRegionKHR raygen{self.m_sbtAddress + s.raygen.offset, s.raygen.stride, s.raygen.size};
        const VkStridedDeviceAddressRegionKHR miss{self.m_sbtAddress + s.miss.offset, s.miss.stride, s.miss.size};
        const VkStridedDeviceAddressRegionKHR hit{self.m_sbtAddress + s.hit.offset, s.hit.stride, s.hit.size};
        const VkStridedDeviceAddressRegionKHR callable{0, 0, 0};
        reinterpret_cast<PFN_vkCmdTraceRaysKHR>(self.m_traceRays)(cmd, &raygen, &miss, &hit, &callable, w, h, 1u);
        return;
    }
#endif
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    vkCmdPushConstants(cmd, layout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PtPush), &r.push);
    vkCmdDispatch(cmd, groups(w, kPtTile), groups(h, kPtTile), 1u);
#else
    (void)context;
    (void)user;
#endif
}

} // namespace fuse::renderer::pathtrace
